1212: 			    struct ieee80211_mgmt *mgmt, size_t len)
1213: {
1214: 	struct ieee80211_local *local = sdata->local;
1215: 	struct ieee80211_if_mesh *ifmsh = &sdata->u.mesh;
1216: 	struct sk_buff *presp;
1217: 	struct beacon_data *bcn;
1218: 	struct ieee80211_mgmt *hdr;
1219: 	struct ieee802_11_elems *elems;
1220: 	size_t baselen;
1221: 	u8 *pos;
1222: 
1223: 	pos = mgmt->u.probe_req.variable;
1224: 	baselen = (u8 *) pos - (u8 *) mgmt;
1225: 	if (baselen > len)
1226: 		return;
1227: 
1228: 	elems = ieee802_11_parse_elems(pos, len - baselen, false, mgmt->bssid,
1229: 				       NULL);
1230: 	if (!elems)
1231: 		return;
1232: 
1233: 	if (!elems->mesh_id)
1234: 		goto free;
1235: 
1236: 	/* 802.11-2012 10.1.4.3.2 */
1237: 	if ((!ether_addr_equal(mgmt->da, sdata->vif.addr) &&
1238: 	     !is_broadcast_ether_addr(mgmt->da)) ||
1239: 	    elems->ssid_len != 0)
1240: 		goto free;
1241: 
1242: 	if (elems->mesh_id_len != 0 &&
1243: 	    (elems->mesh_id_len != ifmsh->mesh_id_len ||
1244: 	     memcmp(elems->mesh_id, ifmsh->mesh_id, ifmsh->mesh_id_len)))
1245: 		goto free;
1246: 
1247: 	rcu_read_lock();
1248: 	bcn = rcu_dereference(ifmsh->beacon);
1249: 
1250: 	if (!bcn)
1251: 		goto out;
1252: 
1253: 	presp = dev_alloc_skb(local->tx_headroom +
1254: 			      bcn->head_len + bcn->tail_len);
1255: 	if (!presp)
1256: 		goto out;
1257: 
